<script lang="ts">
import Icon from './Icon.svelte';import {exportFeedback} from './export-feedback';import FoodSticker from './FoodSticker.svelte';import CalendarDialog from './CalendarDialog.svelte';import ShareDialog from './ShareDialog.svelte';import {renderCard,pngBytes} from './achievement-card';import {achievementValue,searchDays} from './appointment';import {formatDuration} from './statistics';import {copyAppointmentField,loadPublicAchievement,achievementExport,openPublicLink,type Achievement} from './bridge';
let {profile,item,t,language,dark,onedit,onback}:{profile:string;item:Achievement;t:(key:string)=>string;language:string;dark:boolean;onedit:()=>void;onback:()=>void}=$props();
let calendar=$state(false);let network=$state('');let exportBusy=$state(false);let exported=$state('');let exportFailed=$state(false);
let copied=$state('');let failed=$state(false);let copying=$state(false);
const pairs=[['checks','Проверок сит','search'],['active_seconds','Активный поиск','clock'],['offices_seen','Появлений офисов','office'],['unique_offices','Разных офисов','pin'],['booking_screens','Появления выбора даты','calendar'],['flow_passes','Повторные проходы','restart'],['server_errors','Ошибок сервера','server'],['rate_limited','Ограничений HTTP 429','clock'],['blocked','Ограничения доступа','shield'],['first_available_seconds','Первый офис','calendar_days'],['actions_performed','Действий выполнено','pointer'],['pages_processed','Страниц обработано','file_text']];
const days=$derived(searchDays(item));const duration=$derived(days===null?'—':days===0?t('Меньше дня поиска'):t(new Intl.PluralRules(language).select(days)==='one'?'{days} день поиска':new Intl.PluralRules(language).select(days)==='few'?'{days} дня поиска':'{days} дней поиска').replace('{days}',String(days)));
function display(key:string){const value=achievementValue(item.statistics,key,item.statistics_provenance);return key.endsWith('seconds')?formatDuration(value,language):value===null?'—':new Intl.NumberFormat(language).format(value);}
async function copy(field:'office'|'address'|'confirmation'){if(copying)return;copying=true;copied='';failed=false;try{await copyAppointmentField(profile,item.id,field);copied=field;}catch{failed=true;}finally{copying=false;}}
async function image(action:'save_image'|'copy_image'){if(exportBusy)return;exportBusy=true;exportFailed=false;exported='';try{const model=await loadPublicAchievement(profile,item.id,language);const png=await pngBytes(await renderCard(model.layouts[dark?'dark':'light']));const result=await achievementExport(profile,item.id,language,{action,png});exported=exportFeedback(result);}catch{exportFailed=true;}finally{exportBusy=false;}}
async function support(target:'sponsor'|'crypto'){try{await openPublicLink(target,language);}catch{exportFailed=true;}}
</script>
<div class="achievement-page"><button class="flat-action back" onclick={onback}><Icon name="back"/>{t('К статистике')}</button>
<section class="achievement-card"><h2><Icon name="calendar"/>{t('Сита получена')}</h2><strong class="search-duration">{duration}</strong><div class="achievement-grid">{#each pairs as [key,label,icon]}<div class="achievement-metric"><Icon name={icon} size={18}/><span>{t(label)}</span><strong>{display(key)}</strong></div>{/each}</div><p class="muted credit">{t('Получено с помощью Cita Extranjeria Helper')}</p></section>
<section class="appointment-details"><div class="details-heading"><h2><Icon name="calendar_days"/>{t('Данные записи')}</h2><div class="details-actions"><button class="calendar-action" onclick={()=>calendar=true}><Icon name="calendar_days" size={18}/>{t('Добавить в календарь')}</button><button class="icon-button" aria-label={t('Исправить данные записи')} title={t('Исправить данные записи')} onclick={onedit}><Icon name="pencil" size={18}/></button></div></div>
<div class="private-row"><Icon name="clock" size={18}/><span>{t('Дата и время')}</span><strong>{item.appointment.date.split('-').reverse().join('.')} · {item.appointment.time}</strong></div>
{#each [['office','Офис','office'],['address','Адрес','pin'],['confirmation','Номер подтверждения','id']] as [field,label,icon]}{@const value=item.appointment[field as 'office'|'address'|'confirmation']}<div class="private-row"><Icon name={icon} size={18}/><span>{t(label)}</span><strong>{value||'—'}</strong><button class="icon-button" disabled={!value||copying} aria-label={`${t('Копировать')}: ${t(label)}`} title={copied===field?t('Скопировано'):t('Копировать')} onclick={()=>void copy(field as 'office'|'address'|'confirmation')}><Icon name={copied===field?'check':'copy'} size={17}/></button></div>{/each}
<p class="muted privacy"><Icon name="lock" size={15}/>{t('Данные хранятся локально.')}</p>{#if failed}<p role="alert" class="error">{t('Не удалось скопировать')}</p>{/if}</section>
<section class="sharing"><h2><Icon name="share"/>{t('Поделиться достижением')}</h2><div class="social-actions">{#each [['telegram','Telegram'],['x','X'],['facebook','Facebook'],['instagram','Instagram'],['reddit','Reddit']] as [id,label]}<button class="icon-button social" aria-label={label} title={label} onclick={()=>network=id}><img src={`/social/${id}.svg`} alt="" width="23" height="23"/></button>{/each}<span class="social-divider"></span><button disabled={exportBusy} title={exported==='image_saved'?t('Сохранено'):t('Сохранить PNG')} onclick={()=>void image('save_image')}><Icon name={exported==='image_saved'?'check':'download'} size={17}/>{t('Сохранить PNG')}</button><button disabled={exportBusy} title={exported==='image_copied'?t('Скопировано'):t('Копировать PNG')} onclick={()=>void image('copy_image')}><Icon name={exported==='image_copied'?'check':'copy'} size={17}/>{t('Копировать PNG')}</button></div><p class="muted privacy">{t('Только статистика поиска — без даты, времени, офиса и номера подтверждения.')}</p></section>
<section class="donation"><FoodSticker/><div><h2>{t('Поддержать автора')}</h2><p class="muted">{t('Код работает. Автор — за еду.')}</p></div><div class="donation-actions"><button title="GitHub Sponsors" onclick={()=>void support('sponsor')}><Icon name="credit_card"/>{t('Картой')}</button><button title="NOWPayments" onclick={()=>void support('crypto')}><Icon name="bitcoin"/>{t('Криптовалютой')}</button></div></section>
{#if exportFailed}<p class="error" role="alert">{t('Не удалось выполнить действие')}</p>{/if}
</div>
{#if calendar}<CalendarDialog {profile} achievement={item.id} {language} {t} onclose={()=>calendar=false}/>{/if}
{#if network}<ShareDialog {profile} achievement={item.id} {network} {language} {dark} {t} onclose={()=>network=''}/>{/if}
<style>.details-actions{display:flex;gap:8px;align-items:center}.calendar-action{font-size:12px;padding:7px 12px}.sharing{border-top:1px solid var(--line);padding-top:16px}.sharing h2{font-size:16px;margin-bottom:10px}.social-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.social-actions>button{font-size:12px;padding:8px 11px;min-height:36px}.social-actions>.social{padding:5px;border:0;background:none}.social-divider{height:26px;width:1px;background:var(--line);margin:0 3px}.donation{border-top:1px solid var(--line);padding-top:14px;display:flex;gap:12px;align-items:center}.donation>div:first-of-type{flex:1;min-width:0}.donation h2{font-size:15px}.donation p{font-size:12px;margin:5px 0 0}.donation-actions{display:flex;gap:8px}.donation button{padding:7px 11px;font-size:12px}.achievement-page{display:flex;flex-direction:column;gap:16px}.flat-action{background:none;border:0;padding:5px 0;align-self:flex-start;color:var(--muted)}.achievement-card{border:1px solid var(--line);border-top:5px solid #38AD84;border-radius:8px;padding:18px 20px;background:var(--surface)}h2{display:flex;align-items:center;gap:10px;font-size:18px;margin:0}.search-duration{display:block;font-size:27px;font-weight:600;margin:14px 0 16px}.achievement-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:30px}.achievement-metric{display:flex;align-items:center;gap:8px;border-top:1px solid var(--line);padding:11px 0;min-width:0}.achievement-metric span{flex:1;min-width:0}.achievement-metric strong{white-space:nowrap;font-weight:600;font-variant-numeric:tabular-nums}.credit{font-size:12px;margin:12px 0 0}.details-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px}.details-heading h2{font-size:16px}.private-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid var(--line);min-height:44px}.private-row>span{width:138px;flex:none;color:var(--muted)}.private-row strong{font-weight:400;flex:1;overflow-wrap:anywhere;min-width:0}.private-row .icon-button{width:28px;height:28px;min-height:28px;padding:4px;flex:none}.privacy{display:flex;gap:6px;align-items:center;font-size:12px;margin:10px 0 0}@media(max-width:750px){.achievement-card{padding:15px}.achievement-grid{column-gap:20px}.achievement-metric{font-size:12px}.achievement-metric>:global(svg){width:16px;height:16px}.private-row>span{width:115px;font-size:12px}}
@media(max-width:480px){.achievement-card h2,.sharing h2,.details-heading{flex-wrap:wrap}.achievement-grid{grid-template-columns:minmax(0,1fr)}.search-duration,.private-row strong{overflow-wrap:anywhere;min-width:0}.social-actions,.donation,.donation-actions{flex-wrap:wrap}.social-actions>button,.donation button{flex:1 1 auto}.social-divider{display:none}}</style>
